input.command:
mkdir -p scratch/pixelDungeonProps && cat > scratch/pixelDungeonProps/probe.ts <<'EOF'
import * as THREE from "three";
const mod = await import("../../samples/pixelDungeonProps");
const root = mod.default();
const box = new THREE.Box3().setFromObject(root, true);
let parts = 0, tris = 0;
root.traverse((o: any) => { if (o.isMesh) { parts++; const g = o.geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; } });
console.log("size", box.getSize(new THREE.Vector3()).toArray().map((v)=>v.toFixed(3)), "min", box.min.toArray().map((v)=>v.toFixed(3)), "max", box.max.toArray().map((v)=>v.toFixed(3)));
console.log("parts", parts, "tris", tris);
EOF
npx tsx scratch/pixelDungeonProps/probe.ts 2>&1 | tail -20
